 function filterDevices(){
  const list=$('deviceList');if(!list)return;
  const filters={search:$('macSearch')?.value,code:$('deviceCodeFilter')?.value,platform:$('devicePlatformFilter')?.value,state:$('deviceStateFilter')?.value};
  const rows=[...list.children].filter(card=>card.matches('.device-card,.panel-bulk-row'));
  const matched=rows.filter(card=>window.ELVANOQ_DEVICE_FILTERS.matches(card.dataset,filters));
  const included=new Set(matched);for(const card of rows)card.hidden=!included.has(card);
  const empty=$('deviceFilterEmpty');if(empty)empty.hidden=matched.length>0||!overview?.devices?.length;
  if($('deviceCount'))$('deviceCount').textContent=matched.length+' dispositivo(s) encontrado(s)';
  window.ELVANOQ_PAGES?.filtered(list,matched);window.ELVANOQ_BULK?.update(list);
 }
 document.addEventListener('change',e=>{if(['devicePlatformFilter','deviceStateFilter'].includes(e.target.id))filterDevices();});
 $('deviceCodeFilter')?.addEventListener('input',filterDevices);
