 async function load(){const data=await api('overview',{include_removed:!!$('includeRemoved')?.checked});
  if(document.body.dataset.page==='administrador'&&data.role!=='admin')throw new Error('Esta página é exclusiva do administrador. Acesse Revendedores com sua conta.');
  if(document.body.dataset.view==='login'||(panelView&&document.body.dataset.page==='revendedores'&&data.role==='admin')){window.location.replace(panelPath(data.role));return;}
  render(data);message('deviceMessage','');}

